files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1a1a2e;
  color: #e0e0e0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: #16213e;
  border: 4px solid #0f3460;
  border-radius: 0;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 8px 8px 0 #0f3460;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 20px;
  color: #e94560;
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 #0f3460;
}

.input-group {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

#todo-input {
  flex: 1;
  padding: 12px;
  font-size: 1rem;
  border: 3px solid #0f3460;
  background: #1a1a2e;
  color: #e0e0e0;
  outline: none;
  font-family: inherit;
}

#todo-input:focus {
  border-color: #e94560;
}

#todo-add {
  padding: 12px 20px;
  font-size: 1rem;
  background: #e94560;
  color: #fff;
  border: 3px solid #0f3460;
  cursor: pointer;
  font-family: inherit;
  font-weight: bold;
  text-transform: uppercase;
  transition: background 0.1s, transform 0.1s;
}

#todo-add:hover {
  background: #ff6b81;
}

#todo-add:active {
  transform: translate(2px, 2px);
}

#todo-add:focus-visible {
  outline: 2px solid #e94560;
  outline-offset: 2px;
}

.counts {
  display: flex;
  gap: 24px;
  margin-bottom: 16px;
  font-size: 1rem;
  color: #a0a0b0;
}

.counts span span {
  color: #e94560;
  font-weight: bold;
}

.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: #1a1a2e;
  border: 2px solid #0f3460;
}

.todo-item input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: #e94560;
  cursor: pointer;
  flex-shrink: 0;
}

.todo-item input[type="checkbox"]:focus-visible {
  outline: 2px solid #e94560;
  outline-offset: 2px;
}

.todo-item .todo-text {
  flex: 1;
  font-size: 1rem;
  word-break: break-word;
}

.todo-item .todo-text.completed {
  text-decoration: line-through;
  color: #6a6a8a;
}

.todo-item .todo-delete {
  background: transparent;
  border: 2px solid #e94560;
  color: #e94560;
  padding: 4px 10px;
  font-size: 0.875rem;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.1s, color 0.1s;
  flex-shrink: 0;
}

.todo-item .todo-delete:hover {
  background: #e94560;
  color: #fff;
}

.todo-item .todo-delete:active {
  transform: translate(1px, 1px);
}

.todo-item .todo-delete:focus-visible {
  outline: 2px solid #e94560;
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .input-group {
    flex-direction: column;
  }
  #todo-add {
    width: 100%;
  }
}

(() => {
  'use strict';

  const input = document.getElementById('todo-input');
  const addBtn = document.getElementById('todo-add');
  const totalEl = document.getElementById('todo-total');
  const remainingEl = document.getElementById('remaining');
  const list = document.getElementById('todo-list');

  let nextId = 1;
  const tasks = [];

  function updateCounts() {
    totalEl.textContent = tasks.length;
    remainingEl.textContent = tasks.filter(t => !t.completed).length;
  }

  function createTaskElement(task) {
    const li = document.createElement('li');
    li.className = 'todo-item';
    li.dataset.id = task.id;

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = `todo-check-${task.id}`;
    checkbox.checked = task.completed;
    checkbox.setAttribute('aria-label', `Mark "${task.text}" as completed`);
    checkbox.addEventListener('change', () => {
      task.completed = checkbox.checked;
      textSpan.classList.toggle('completed', task.completed);
      updateCounts();
    });

    const textSpan = document.createElement('span');
    textSpan.className = 'todo-text';
    textSpan.id = `todo-text-${task.id}`;
    textSpan.textContent = task.text;
    if (task.completed) textSpan.classList.add('completed');

    const deleteBtn = document.createElement('button');
    deleteBtn.type = 'button';
    deleteBtn.className = 'todo-delete';
    deleteBtn.id = `todo-delete-${task.id}`;
    deleteBtn.textContent = 'Delete';
    deleteBtn.setAttribute('aria-label', `Delete task "${task.text}"`);
    deleteBtn.addEventListener('click', () => {
      const idx = tasks.findIndex(t => t.id === task.id);
      if (idx !== -1) tasks.splice(idx, 1);
      li.remove();
      updateCounts();
    });

    li.append(checkbox, textSpan, deleteBtn);
    return li;
  }

  function addTask() {
    const text = input.value.trim();
    if (!text) return;

    const task = { id: nextId++, text, completed: false };
    tasks.push(task);
    list.appendChild(createTaskElement(task));
    input.value = '';
    input.focus();
    updateCounts();
  }

  addBtn.addEventListener('click', addTask);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') addTask();
  });

  updateCounts();
})();
